<?php require '../includes/auth.php';require_role('buyer');$pdo=db();$edit=null;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=post('action');$id=(int)post('id');if($action==='delete'){$pdo->prepare('DELETE FROM buyer_addresses WHERE id=? AND user_id=?')->execute([$id,user()['id']]);flash('success','Address removed.');redirect('buyer/addresses.php');}$label=post('label');$name=post('recipient_name');$phone=post('phone');$line=post('address_line');$city=post('city');$pin=post('postal_code');if(!$label||!$name||!$phone||!$line||!$city)$error='Please fill in all required address fields.';else{try{$pdo->beginTransaction();if(isset($_POST['is_default']))$pdo->prepare('UPDATE buyer_addresses SET is_default=0 WHERE user_id=?')->execute([user()['id']]);if($action==='update')$pdo->prepare('UPDATE buyer_addresses SET label=?,recipient_name=?,phone=?,address_line=?,city=?,postal_code=?,is_default=? WHERE id=? AND user_id=?')->execute([$label,$name,$phone,$line,$city,$pin,isset($_POST['is_default']),$id,user()['id']]);else $pdo->prepare('INSERT INTO buyer_addresses(user_id,label,recipient_name,phone,address_line,city,postal_code,is_default) VALUES(?,?,?,?,?,?,?,?)')->execute([user()['id'],$label,$name,$phone,$line,$city,$pin,isset($_POST['is_default'])]);$pdo->commit();flash('success','Address saved.');redirect('buyer/addresses.php');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error='Could not save the address. Please retry.';}}}if(isset($_GET['edit'])){$s=$pdo->prepare('SELECT * FROM buyer_addresses WHERE id=? AND user_id=?');$s->execute([(int)$_GET['edit'],user()['id']]);$edit=$s->fetch();if(!$edit){flash('error','Address not found.');redirect('buyer/addresses.php');}}$s=$pdo->prepare('SELECT * FROM buyer_addresses WHERE user_id=? ORDER BY is_default DESC,id DESC');$s->execute([user()['id']]);$addresses=$s->fetchAll();$pageTitle='Delivery addresses';require '../includes/header.php';?><div class="page-title"><p class="eyebrow">ACCOUNT</p><h1>Delivery addresses</h1></div><?php if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><div class="two-col"><section class="address-list"><?php foreach($addresses as $a):?><article><b><?=e($a['label'])?> <?=$a['is_default']?'<small>DEFAULT</small>':''?></b><p><?=e($a['recipient_name'])?><br><?=e($a['address_line'])?><br><?=e($a['city'])?> — <?=e($a['postal_code'])?><br><?=e($a['phone'])?></p><a href="addresses.php?edit=<?=$a['id']?>">Edit</a> <form class="inline-form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$a['id']?>"><button class="text-button" data-confirm="Remove this address?">Remove</button></form></article><?php endforeach;?></section><form class="card-form" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="<?=$edit?'update':'add'?>"><?php if($edit):?><input type="hidden" name="id" value="<?=$edit['id']?>"><?php endif;?><h2><?=$edit?'Edit address':'Add an address'?></h2><label>Label<input name="label" value="<?=e($edit['label']??'')?>" placeholder="Home" required></label><label>Full name<input name="recipient_name" value="<?=e($edit['recipient_name']??'')?>" required></label><label>Phone<input name="phone" value="<?=e($edit['phone']??'')?>" required></label><label>Address line<textarea name="address_line" required><?=e($edit['address_line']??'')?></textarea></label><label>City / district<input name="city" value="<?=e($edit['city']??'')?>" required></label><label>Pincode<input name="postal_code" value="<?=e($edit['postal_code']??'')?>"></label><label class="check"><input type="checkbox" name="is_default" <?=!$edit||$edit['is_default']?'checked':''?>> Make default</label><button><?=$edit?'Update address':'Add address'?></button><?php if($edit):?><a href="addresses.php">Cancel edit</a><?php endif;?></form></div><?php require '../includes/footer.php'; ?>
